// SAFETY-FIRST retention: NEVER delete old backups unless TODAY's cycle is
// fully present in 03_Backup. If this run's uploads failed/partial, today's
// files are missing -> we THROW (no deletion happens, and 06b error alert
// fires). Old backups are only removed once a complete new cycle exists.
const date = $('Config').first().json.backup_date;
const prefix = date + '__';
const files = [];
for (const it of $input.all()) {
  const f = it.json || {};
  if (f && f.name && f.id) files.push(f);
}
const todays = files.filter(f => f.name.startsWith(prefix));
const hasWorkflowJson = todays.some(f => f.name.endsWith('.json'));
const hasMediaXlsx = todays.some(f => f.name.endsWith('Media.xlsx'));
if (!hasWorkflowJson || !hasMediaXlsx) {
  throw new Error('Backup incomplete for ' + date + ' (workflow .json present: ' + hasWorkflowJson + ', Media .xlsx present: ' + hasMediaXlsx + '). ABORTING retention delete so old backups are preserved.');
}
// Today's cycle is complete -> safe to delete everything NOT from today.
const out = [];
for (const f of files) {
  if (f.name.startsWith(prefix)) continue;   // keep today's cycle
  out.push({ json: { id: f.id, name: f.name } });
}
return out;

// LIVE path (enable with Get Workflows). Keep only xx_ workflows, one importable
// .json each, prefixed with the backup date.
const date = $('Config').first().json.backup_date;
const out = [];
for (const it of $input.all()) {
  const wf = it.json || {};
  const name = wf.name || '';
  if (!/^\d+_/.test(name)) continue;
  const str = JSON.stringify(wf, null, 2);
  const safe = name.replace(/[\\/:*?"<>|]/g, '_');
  const fileName = date + '__' + safe + '.json';
  out.push({ json: { fileName, workflow_name: name }, binary: { data: await this.helpers.prepareBinaryData(Buffer.from(str, 'utf8'), fileName, 'application/json') } });
}
if (out.length === 0) throw new Error('No xx_ workflows found to back up');
return out;
